  color-scheme: dark;
  --bg: #0d1117;
  --bg-deep: #070a0f;
  --panel: rgba(22, 27, 34, 0.78);
  --panel-strong: #111821;
  --panel-soft: rgba(71, 95, 145, 0.12);
  --line: rgba(148, 163, 184, 0.18);
  --line-strong: rgba(148, 163, 184, 0.32);
  --text: #f8fafc;
  --muted: #9ca3af;
  --subtle: #cbd5e1;
  --accent: #27f5c5;
  --accent-2: #38bdf8;
  --accent-blue: #7da2ff;
  --warn: #facc15;
  --radius-lg: 28px;
  --radius: 18px;
  --radius-sm: 12px;
  --shadow: 0 24px 80px rgba(0, 0, 0, 0.38);
  --max: 1180px;
  --font-sans: Inter, ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", sans-serif;
  --font-mono: "SFMono-Regular", Consolas, "Liberation Mono", Menlo, monospace;
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background:
    radial-gradient(circle at 18% -10%, rgba(39, 245, 197, 0.14), transparent 34rem),
    radial-gradient(circle at 82% 5%, rgba(56, 189, 248, 0.13), transparent 30rem),
    linear-gradient(180deg, var(--bg), var(--bg-deep) 64%);
  color: var(--text);
  font-family: var(--font-sans);
  line-height: 1.6;
  min-height: 100vh;
}

a { color: inherit; text-decoration: none; }
button, input { font: inherit; }
.skip-link {
  position: absolute;
  left: 16px;
  top: -80px;
  z-index: 100;
  background: var(--accent);
  color: #001914;
  padding: 10px 14px;
  border-radius: 999px;
  font-weight: 800;
}
.skip-link:focus { top: 12px; }

.site-header {
  position: sticky;
  top: 0;
  z-index: 50;
  backdrop-filter: blur(18px);
  background: rgba(13, 17, 23, 0.78);
  border-bottom: 1px solid var(--line);
}
.nav-shell {
  max-width: var(--max);
  margin: 0 auto;
  padding: 14px 24px;
  display: flex;
  align-items: center;
  gap: 22px;
}
.brand {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  font-weight: 800;
  letter-spacing: -0.02em;
  white-space: nowrap;
}
.logo-mark {
  width: 32px;
  height: 32px;
  display: grid;
  place-items: center;
  border-radius: 10px;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  color: #041012;
  box-shadow: 0 0 28px rgba(39, 245, 197, 0.28);
}
.top-nav {
  display: flex;
  align-items: center;
  gap: 4px;
  margin-left: auto;
}
.top-nav a {
  color: var(--subtle);
  min-height: 44px;
  display: inline-flex;
  align-items: center;
  border-radius: 999px;
  padding: 0 13px;
  font-size: 0.94rem;
}
.top-nav a:hover, .top-nav a.active {
  color: var(--text);
  background: rgba(255,255,255,0.07);
}
.header-actions { display: flex; align-items: center; gap: 10px; }
.search-pill, .icon-button {
  min-height: 44px;
  border: 1px solid var(--line);
  background: rgba(255,255,255,0.04);
  color: var(--subtle);
  border-radius: 999px;
}
.search-pill {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  padding: 0 14px;
}
.icon-button {
  width: 44px;
  display: grid;
  place-items: center;
}
.mobile-menu-button { display: none; }

main { overflow: clip; }
.container { max-width: var(--max); margin: 0 auto; padding: 0 24px; }
.section { padding: 72px 0; }
.hero { padding: 92px 0 56px; }
.hero-grid {
  display: grid;
  grid-template-columns: minmax(0, 1.05fr) minmax(320px, 0.72fr);
  gap: 44px;
  align-items: center;
}
.eyebrow {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--accent);
  font-weight: 750;
  font-size: 0.84rem;
  text-transform: uppercase;
  letter-spacing: 0.13em;
  margin-bottom: 16px;
}
h1, h2, h3 { line-height: 1.04; letter-spacing: -0.045em; margin: 0; }
h1 { font-size: clamp(3rem, 8vw, 6.7rem); max-width: 960px; }
h2 { font-size: clamp(2rem, 4vw, 3.5rem); }
h3 { font-size: 1.2rem; letter-spacing: -0.025em; }
p { color: var(--subtle); margin: 0; }
.lede { font-size: clamp(1.06rem, 2vw, 1.28rem); max-width: 760px; margin-top: 22px; }
.hero-actions, .button-row { display: flex; flex-wrap: wrap; gap: 12px; margin-top: 30px; }
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  min-height: 46px;
  padding: 0 18px;
  border-radius: 999px;
  border: 1px solid var(--line-strong);
  color: var(--text);
  background: rgba(255,255,255,0.05);
  font-weight: 750;
}
.btn.primary {
  color: #001914;
  border-color: transparent;
  background: linear-gradient(135deg, var(--accent), var(--accent-2));
  box-shadow: 0 14px 46px rgba(39, 245, 197, 0.20);
}
.btn:hover { transform: translateY(-1px); border-color: rgba(39,245,197,0.55); }

.terminal-card, .glass-card, .doc-card, .resource-card, .launch-card {
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(255,255,255,0.055), rgba(255,255,255,0.026));
  box-shadow: var(--shadow);
  backdrop-filter: blur(18px);
}
.terminal-card { border-radius: var(--radius-lg); overflow: hidden; }
.terminal-bar {
  display: flex;
  gap: 8px;
  align-items: center;
  padding: 15px 18px;
  border-bottom: 1px solid var(--line);
  background: rgba(0,0,0,0.22);
}
.dot { width: 11px; height: 11px; border-radius: 999px; background: #f87171; }
.dot:nth-child(2) { background: #fbbf24; }
.dot:nth-child(3) { background: #34d399; }
.terminal-title { margin-left: auto; color: var(--muted); font: 700 0.76rem var(--font-mono); }
pre, code { font-family: var(--font-mono); }
pre {
  margin: 0;
  padding: 22px;
  overflow-x: auto;
  color: #dbeafe;
  font-size: 0.91rem;
  line-height: 1.75;
}
.code-accent { color: var(--accent); }
.code-muted { color: #64748b; }
.code-blue { color: #93c5fd; }
.code-warn { color: var(--warn); }

.section-head {
  display: flex;
  align-items: end;
  justify-content: space-between;
  gap: 24px;
  margin-bottom: 28px;
}
.section-head p { max-width: 650px; margin-top: 12px; }
.grid-3 { display: grid; grid-template-columns: repeat(3, 1fr); gap: 18px; }
.grid-2 { display: grid; grid-template-columns: repeat(2, 1fr); gap: 18px; }
.grid-auto { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 16px; }
.product-card, .doc-card, .resource-card, .launch-card, .stat-card {
  position: relative;
  border-radius: var(--radius);
  padding: 24px;
  overflow: hidden;
}
.product-card {
  min-height: 290px;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--line);
  background: linear-gradient(145deg, rgba(255,255,255,0.07), rgba(255,255,255,0.025));
}
.product-card::before {
  content: "";
  position: absolute;
  inset: 0;
  background: radial-gradient(circle at top right, var(--card-glow), transparent 55%);
  opacity: 0.8;
}
.product-card > * { position: relative; }
.card-icon {
  width: 48px;
  height: 48px;
  display: grid;
  place-items: center;
  border-radius: 16px;
  background: rgba(255,255,255,0.08);
  border: 1px solid var(--line);
  margin-bottom: 36px;
  font-size: 1.35rem;
}
.product-card p, .doc-card p, .resource-card p, .launch-card p { margin-top: 12px; }
.card-link { margin-top: auto; color: var(--accent); font-weight: 800; padding-top: 26px; }

.cli-panel {
  display: grid;
  grid-template-columns: 0.9fr 1.1fr;
  gap: 18px;
  align-items: start;
}
.accordion-list { display: grid; gap: 10px; }
.accordion-item {
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(255,255,255,0.035);
  overflow: hidden;
}
.accordion-trigger {
  width: 100%;
  min-height: 64px;
  padding: 0 18px;
  border: 0;
  background: transparent;
  color: var(--text);
  display: flex;
  align-items: center;
  justify-content: space-between;
  cursor: pointer;
  font-weight: 850;
}
.accordion-trigger span:last-child { color: var(--accent); transition: transform .2s ease; }
.accordion-item.open .accordion-trigger span:last-child { transform: rotate(45deg); }
.accordion-content { display: none; padding: 0 18px 18px; }
.accordion-item.open .accordion-content { display: block; }
.accordion-content ol { margin: 0; padding-left: 20px; color: var(--subtle); }
.accordion-content li + li { margin-top: 10px; }
.code-panel {
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: #080c12;
  overflow: hidden;
  position: sticky;
  top: 92px;
}
.tabs {
  display: flex;
  gap: 4px;
  padding: 10px;
  border-bottom: 1px solid var(--line);
  background: rgba(255,255,255,0.035);
}
.tab {
  border: 0;
  min-height: 40px;
  padding: 0 14px;
  border-radius: 999px;
  color: var(--muted);
  background: transparent;
  cursor: pointer;
  font-weight: 800;
}
.tab.active { background: rgba(39,245,197,0.13); color: var(--accent); }
.code-panel pre { min-height: 230px; }

.band {
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: 32px;
  background: linear-gradient(135deg, rgba(39,245,197,0.10), rgba(56,189,248,0.07) 48%, rgba(255,255,255,0.035));
}
.footer {
  border-top: 1px solid var(--line);
  padding: 44px 0;
  background: rgba(0,0,0,0.18);
}
.footer-grid { display: grid; grid-template-columns: 1.3fr repeat(4, 1fr); gap: 28px; }
.footer h3 { font-size: 0.88rem; letter-spacing: 0; margin-bottom: 12px; }
.footer a, .footer p { color: var(--muted); display: block; margin: 8px 0; font-size: 0.92rem; }

.docs-layout {
  max-width: 1440px;
  margin: 0 auto;
  display: grid;
  grid-template-columns: 280px minmax(0, 1fr);
  gap: 28px;
  padding: 28px 24px 0;
  transition: grid-template-columns .25s ease;
}
.docs-layout.collapsed { grid-template-columns: 76px minmax(0, 1fr); }
.sidebar {
  position: sticky;
  top: 86px;
  height: calc(100vh - 104px);
  align-self: start;
  border: 1px solid var(--line);
  border-radius: var(--radius);
  background: rgba(13,17,23,0.82);
  backdrop-filter: blur(18px);
  padding: 14px;
  overflow: hidden;
}
.sidebar-toggle {
  width: 100%;
  min-height: 44px;
  border: 1px solid var(--line);
  border-radius: 12px;
  background: rgba(255,255,255,0.04);
  color: var(--text);
  cursor: pointer;
  margin-bottom: 12px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  font-weight: 800;
}
.sidebar nav { display: grid; gap: 4px; }
.sidebar a {
  min-height: 40px;
  display: flex;
  align-items: center;
  gap: 10px;
  border-radius: 10px;
  padding: 0 10px;
  color: var(--subtle);
  white-space: nowrap;
}
.sidebar a:hover, .sidebar a.active { color: var(--text); background: rgba(255,255,255,0.07); }
.sidebar .glyph { width: 22px; text-align: center; flex: 0 0 22px; }
.docs-layout.collapsed .sidebar .label, .docs-layout.collapsed .sidebar-toggle .label { display: none; }
.doc-main { min-width: 0; }
.doc-hero {
  border: 1px solid var(--line);
  border-radius: var(--radius-lg);
  padding: clamp(32px, 6vw, 70px);
  background:
    radial-gradient(circle at 80% 15%, rgba(39,245,197,0.15), transparent 30rem),
    linear-gradient(145deg, rgba(255,255,255,0.07), rgba(255,255,255,0.025));
}
.doc-section { padding: 56px 0; border-bottom: 1px solid var(--line); }
.doc-section:last-child { border-bottom: 0; }
.doc-section > p { max-width: 820px; margin-top: 14px; }
.doc-card { min-height: 170px; }
.doc-card code, .inline-code {
  color: var(--accent);
  background: rgba(39,245,197,0.08);
  border: 1px solid rgba(39,245,197,0.18);
  padding: 2px 6px;
  border-radius: 7px;
}
.mini-list { display: grid; gap: 12px; margin-top: 20px; }
.mini-list div {
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 16px;
  background: rgba(255,255,255,0.035);
}
.actor-diagram {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 14px;
  margin-top: 26px;
}
.actor {
  min-height: 180px;
  border-radius: var(--radius);
  border: 1px solid var(--line);
  background: linear-gradient(180deg, rgba(39,245,197,0.10), rgba(255,255,255,0.035));
  padding: 22px;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
}
.actor strong { font-size: 1.5rem; letter-spacing: -0.04em; }
.status-pill {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  min-height: 32px;
  padding: 0 10px;
  border-radius: 999px;
  background: rgba(250,204,21,0.12);
  color: #fde68a;
  border: 1px solid rgba(250,204,21,0.24);
  font-weight: 800;
  margin-top: 16px;
}
.support-hero { text-align: center; max-width: 820px; margin: 0 auto; }
.support-hero .hero-actions { justify-content: center; }

@media (max-width: 1020px) {
  .hero-grid, .cli-panel, .footer-grid { grid-template-columns: 1fr; }
  .grid-3, .grid-auto { grid-template-columns: repeat(2, 1fr); }
  .docs-layout { grid-template-columns: 76px minmax(0,1fr); }
  .docs-layout .sidebar .label, .docs-layout .sidebar-toggle .label { display: none; }
  .actor-diagram { grid-template-columns: repeat(2, 1fr); }
  .top-nav {
    display: none;
    position: absolute;
    left: 16px;
    right: 16px;
    top: 68px;
    flex-direction: column;
    align-items: stretch;
    background: rgba(13,17,23,0.98);
    border: 1px solid var(--line);
    border-radius: 18px;
    padding: 12px;
  }
  .site-header.menu-open .top-nav { display: flex; }
  .mobile-menu-button { display: grid; }
  .search-pill { display: none; }
}
@media (max-width: 720px) {
  .container, .nav-shell { padding-left: 16px; padding-right: 16px; }
  .hero { padding-top: 60px; }
  .section { padding: 48px 0; }
  .grid-3, .grid-2, .grid-auto, .actor-diagram { grid-template-columns: 1fr; }
  .section-head { display: block; }
  .docs-layout { display: block; padding: 16px; }
  .sidebar { position: relative; top: 0; height: auto; margin-bottom: 18px; }
  .sidebar nav { grid-template-columns: repeat(2, 1fr); }
  .docs-layout .sidebar .label, .docs-layout .sidebar-toggle .label { display: inline; }
  .footer-grid { gap: 18px; }
  .brand span:last-child { display: none; }
  h1 { font-size: clamp(2.55rem, 15vw, 4rem); }
}
EOF

cat > /app/output/assets/app.js <<'EOF'
const header = document.querySelector('.site-header');
const menuButton = document.querySelector('[data-menu-toggle]');
if (menuButton && header) {
  menuButton.addEventListener('click', () => {
    const open = header.classList.toggle('menu-open');
    menuButton.setAttribute('aria-expanded', String(open));
  });
}

const cliData = {
  apps: {
    title: 'Apps',
    init: 'commerceforge app init',
    comment: 'Create a new CommerceForge app in a subdirectory'
  },
  themes: {
    title: 'Themes',
    init: 'commerceforge theme init',
    comment: 'Clone a starter theme with live store data'
  },
  headless: {
    title: 'Headless storefronts',
    init: 'commerceforge hydrogen init',
    comment: 'Initialize a Hydrogen storefront'
  }
};
const installCommands = {
  npm: 'npm i -g @commerceforge/cli@latest',
  yarn: 'yarn global add @commerceforge/cli@latest',
  pnpm: 'pnpm add -g @commerceforge/cli@latest'
};
let activeCli = 'apps';
let activePackage = 'npm';
function renderCliCode() {
  const code = document.querySelector('[data-cli-code]');
  if (!code) return;
  const data = cliData[activeCli];
  code.innerHTML = `<span class="code-muted"># Install CommerceForge CLI 3.0</span>\n<span class="code-accent">${installCommands[activePackage]}</span>\n\n<span class="code-muted"># ${data.comment}</span>\n<span class="code-blue">${data.init}</span>\n\n<span class="code-muted"># Start local development</span>\n<span class="code-warn">commerceforge dev</span>`;
}

document.querySelectorAll('[data-accordion]').forEach((trigger) => {
  trigger.addEventListener('click', () => {
    const key = trigger.dataset.accordion;
    activeCli = key;
    document.querySelectorAll('.accordion-item').forEach((item) => {
      const isOpen = item.dataset.item === key;
      item.classList.toggle('open', isOpen);
      const button = item.querySelector('[data-accordion]');
      const panel = item.querySelector('.accordion-content');
      button.setAttribute('aria-expanded', String(isOpen));
      panel.hidden = !isOpen;
    });
    renderCliCode();
  });
});

document.querySelectorAll('[data-package]').forEach((tab) => {
  tab.addEventListener('click', () => {
    activePackage = tab.dataset.package;
    document.querySelectorAll('[data-package]').forEach((item) => {
      const selected = item === tab;
      item.classList.toggle('active', selected);
      item.setAttribute('aria-selected', String(selected));
    });
    renderCliCode();
  });
});
renderCliCode();

document.querySelectorAll('[data-sidebar-toggle]').forEach((button) => {
  button.addEventListener('click', () => {
    const layout = button.closest('.docs-layout');
    const collapsed = layout.classList.toggle('collapsed');
    button.setAttribute('aria-expanded', String(!collapsed));
  });
});
EOF

