from html.parser import HTMLParser
from pathlib import Path
root=Path('/app/output')
class P(HTMLParser):
    def __init__(self): super().__init__(); self.hrefs=[]; self.scripts=[]; self.css=[]
    def handle_starttag(self, tag, attrs):
        d=dict(attrs)
        if tag=='a' and 'href' in d: self.hrefs.append(d['href'])
        if tag=='script' and 'src' in d: self.scripts.append(d['src'])
        if tag=='link' and d.get('rel')=='stylesheet': self.css.append(d.get('href',''))
errors=[]
for page in root.glob('*.html'):
    p=P(); p.feed(page.read_text())
    for ref in p.scripts+p.css:
        if not (page.parent/ref.split('#')[0]).exists(): errors.append(f'{page.name}: missing asset {ref}')
    for href in p.hrefs:
        if href.startswith(('#','http','mailto:')) or href=='': continue
        target=href.split('#')[0]
        if target and not (page.parent/target).exists(): errors.append(f'{page.name}: missing link {href}')
if errors:
    print('\n'.join(errors)); raise SystemExit(1)
print('HTML asset/link checks OK')
